-- KYC document fields and admin review helper\nALTER TABLE public.kyc_submissions ADD COLUMN IF NOT EXISTS mobile_number text;\nALTER TABLE public.kyc_submissions ADD COLUMN IF NOT EXISTS document_front_url text;\nALTER TABLE public.kyc_submissions ADD COLUMN IF NOT EXISTS document_back_url text;\nALTER TABLE public.kyc_submissions ADD COLUMN IF NOT EXISTS pan_document_url text;\n\nCREATE OR REPLACE FUNCTION public.admin_review_kyc(p_id uuid, p_status public.kyc_status, p_note text DEFAULT NULL)\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE v_user uuid;\nBEGIN\n  IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin only'; END IF;\n  SELECT user_id INTO v_user FROM public.kyc_submissions WHERE id = p_id;\n  IF v_user IS NULL THEN RAISE EXCEPTION 'KYC submission not found'; END IF;\n  UPDATE public.kyc_submissions SET status = p_status, admin_note = p_note WHERE id = p_id;\n  UPDATE public.profiles SET kyc_status = p_status WHERE id = v_user;\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.admin_review_kyc(uuid, public.kyc_status, text) TO authenticated;\n